package com.troday.api.service;

import com.fasterxml.jackson.databind.JsonNode; import com.troday.api.dto.ApiResponseDto; import com.troday.api.entity.*; import com.troday.api.repository.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.transaction.Transactional; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter; import java.time.LocalDateTime; import java.util.*;

@Service public class MessagingService {
 private final AccountService accounts; private final ConversationRepository conversations; private final ConversationParticipantRepository participants; private final ChatMessageRepository messages; private final NotificationRepository notifications; private final PostRepository posts; private final RoommateRequestRepository roommateRequests;
 public MessagingService(AccountService a,ConversationRepository c,ConversationParticipantRepository p,ChatMessageRepository m,NotificationRepository n,PostRepository posts,RoommateRequestRepository rr){accounts=a;conversations=c;participants=p;messages=m;notifications=n;this.posts=posts;roommateRequests=rr;}
 @Transactional public ApiResponseDto<?> roomInquiry(HttpServletRequest r,JsonNode b){Long me=accounts.authenticatedUserId(r);Long postId=requiredLong(b,"postId");Post post=posts.findById(postId).filter(this::publicPost).orElseThrow(()->notFound("Tin không còn khả dụng"));Conversation c=conversations.findByPostIdAndType(postId,"ROOM_INQUIRY").orElseGet(()->newConversation("ROOM_INQUIRY",post.getRoomId(),postId,null));c=conversations.save(c);ensureParticipant(c.getId(),me);ensureParticipant(c.getId(),post.getLandlordId());return ok("POST",conversationData(c));}
 public ApiResponseDto<?> list(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);List<Map<String,Object>> out=participants.findByUserId(me).stream().map(p->conversations.findById(p.getConversationId()).map(this::conversationData).orElse(null)).filter(Objects::nonNull).toList();return ok("GET",out);}
 public ApiResponseDto<?> detail(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);Conversation c=member(id,me);return ok("GET",conversationData(c));}
 public ApiResponseDto<?> messageList(HttpServletRequest r,Long id){Long me=accounts.authenticatedUserId(r);member(id,me);return ok("GET",messages.findByConversationIdOrderBySentAtAscIdAsc(id).stream().map(this::messageData).toList());}
 @Transactional public ApiResponseDto<?> sendMessage(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);member(id,me);String key=text(b,"clientMessageKey"),type=text(b,"type");if(key.isBlank())throw bad("clientMessageKey là bắt buộc");if(!Set.of("TEXT","IMAGE").contains(type))throw bad("type phải là TEXT hoặc IMAGE");if("TEXT".equals(type)&&text(b,"content").isBlank())throw bad("content là bắt buộc");Optional<ChatMessage> old=messages.findBySenderIdAndClientMessageKey(me,key);if(old.isPresent())return ok("POST",messageData(old.get()));ChatMessage m=new ChatMessage();m.setConversationId(id);m.setSenderId(me);m.setClientMessageKey(key);m.setMessageType(type);m.setContent(text(b,"content"));m.setSentAt(LocalDateTime.now());m=messages.save(m);Conversation c=conversations.findById(id).orElseThrow();c.setLastMessageId(m.getId());c.setLastMessageAt(m.getSentAt());conversations.save(c);for(ConversationParticipant p:participants.findByConversationId(id))if(!p.getUserId().equals(me)&&!p.isMuted())createNotification(p.getUserId(),"NEW_MESSAGE","Tin nhắn mới","Bạn có tin nhắn mới", "CONVERSATION",id,"message:"+m.getId());return ok("POST",Map.of("message",messageData(m),"eventId","message:"+m.getId()));}
 @Transactional public ApiResponseDto<?> readState(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);member(id,me);Long messageId=requiredLong(b,"lastReadMessageId");ChatMessage m=messages.findById(messageId).orElseThrow(()->notFound("Không tìm thấy tin nhắn"));if(!m.getConversationId().equals(id))throw bad("Tin nhắn không thuộc hội thoại");ConversationParticipant p=participants.findByConversationIdAndUserId(id,me).orElseThrow();p.setLastReadAt(m.getSentAt());participants.save(p);return ok("PUT",Map.of("conversationId",id,"lastReadAt",m.getSentAt(),"unreadCount",0));}
 @Transactional public ApiResponseDto<?> preferences(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);member(id,me);ConversationParticipant p=participants.findByConversationIdAndUserId(id,me).orElseThrow();if(b.has("muted"))p.setMuted(b.get("muted").asBoolean());if(b.has("archived"))p.setArchived(b.get("archived").asBoolean());if(b.has("deleted"))p.setDeleted(b.get("deleted").asBoolean());participants.save(p);return ok("PATCH",Map.of("conversationId",id,"muted",p.isMuted(),"archived",p.isArchived(),"deleted",p.isDeleted()));}
 public ApiResponseDto<?> viewingTimeline(HttpServletRequest r,Long id){member(id,accounts.authenticatedUserId(r));return ok("GET",Map.of("viewings",List.of(),"proposals",List.of()));}
 @Transactional public ApiResponseDto<?> roommateConversation(HttpServletRequest r,Long requestId){Long me=accounts.authenticatedUserId(r);RoommateRequest x=roommateRequests.findById(requestId).orElseThrow(()->notFound("Không tìm thấy kết nối"));if(!x.getSenderId().equals(me)&&!x.getReceiverId().equals(me))throw forbidden("Không phải thành viên kết nối");if(!"ACCEPTED".equals(x.getStatus())||x.getEndedAt()!=null)throw conflict("Kết nối đã kết thúc");Conversation c=conversations.findByRoommateRequestId(requestId).orElseGet(()->newConversation("ROOMMATE",null,null,requestId));c=conversations.save(c);ensureParticipant(c.getId(),x.getSenderId());ensureParticipant(c.getId(),x.getReceiverId());return ok("POST",conversationData(c));}
 @Transactional public ApiResponseDto<?> sharePost(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);member(id,me);Long postId=requiredLong(b,"postId");Post p=posts.findById(postId).filter(this::publicPost).orElseThrow(()->notFound("Tin không còn khả dụng"));String key=text(b,"clientMessageKey");if(key.isBlank())throw bad("clientMessageKey là bắt buộc");Optional<ChatMessage> old=messages.findBySenderIdAndClientMessageKey(me,key);if(old.isPresent())return ok("POST",messageData(old.get()));ChatMessage m=new ChatMessage();m.setConversationId(id);m.setSenderId(me);m.setClientMessageKey(key);m.setMessageType("POST_SHARE");m.setSharedPostId(p.getId());m.setSentAt(LocalDateTime.now());m=messages.save(m);return ok("POST",messageData(m));}
 public ApiResponseDto<?> notificationList(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);String read=r.getParameter("isRead"),type=r.getParameter("type");return ok("GET",notifications.findByUserIdOrderByCreatedAtDesc(me).stream().filter(n->read==null||Boolean.valueOf(read)==n.isRead()).filter(n->type==null||type.equals(n.getType())).map(this::notificationData).toList());}
 public ApiResponseDto<?> notificationCounts(HttpServletRequest r){Long me=accounts.authenticatedUserId(r);long unread=notifications.countByUserIdAndReadFalse(me);long msg=participants.findByUserId(me).stream().mapToLong(p->messages.countByConversationIdAndSenderIdNot(p.getConversationId(),me)).sum();return ok("GET",Map.of("notificationsUnread",unread,"messagesUnread",msg));}
 @Transactional public ApiResponseDto<?> notificationRead(HttpServletRequest r,Long id,JsonNode b){Long me=accounts.authenticatedUserId(r);Notification n=notifications.findById(id).filter(x->x.getUserId().equals(me)).orElseThrow(()->notFound("Không tìm thấy thông báo"));if(b!=null&&b.has("isRead")&&!b.get("isRead").asBoolean())throw bad("Chỉ hỗ trợ đánh dấu đã đọc");n.setRead(true);n.setReadAt(LocalDateTime.now());return ok("PUT",notificationData(notifications.save(n)));}
 @Transactional public ApiResponseDto<?> notificationReadAll(HttpServletRequest r,JsonNode b){Long me=accounts.authenticatedUserId(r);int count=0;for(Notification n:notifications.findByUserIdOrderByCreatedAtDesc(me))if(!n.isRead()){n.setRead(true);n.setReadAt(LocalDateTime.now());notifications.save(n);count++;}return ok("POST",Map.of("updatedCount",count));}
 public SseEmitter events(HttpServletRequest r){accounts.authenticatedUserId(r);SseEmitter emitter=new SseEmitter(30000L);try{emitter.send(SseEmitter.event().name("connected").id(UUID.randomUUID().toString()).data(Map.of("type","connected","occurredAt",LocalDateTime.now())));emitter.complete();}catch(Exception e){emitter.completeWithError(e);}return emitter;}
 private Conversation newConversation(String type,Long room,Long post,Long request){Conversation c=new Conversation();c.setType(type);c.setRoomId(room);c.setPostId(post);c.setRoommateRequestId(request);return c;}
 private void ensureParticipant(Long cid,Long uid){if(participants.findByConversationIdAndUserId(cid,uid).isEmpty()){ConversationParticipant p=new ConversationParticipant();p.setConversationId(cid);p.setUserId(uid);p.setJoinedAt(LocalDateTime.now());participants.save(p);}}
 private Conversation member(Long id,Long uid){Conversation c=conversations.findById(id).orElseThrow(()->notFound("Không tìm thấy hội thoại"));if(participants.findByConversationIdAndUserId(id,uid).isEmpty())throw forbidden("Bạn không thuộc hội thoại này");return c;}
 private void createNotification(Long uid,String type,String title,String content,String rt,Long rid,String key){if(notifications.findByUserIdAndEventKey(uid,key).isPresent())return;Notification n=new Notification();n.setUserId(uid);n.setType(type);n.setTitle(title);n.setContent(content);n.setResourceType(rt);n.setResourceId(rid);n.setEventKey(key);n.setCreatedAt(LocalDateTime.now());notifications.save(n);}
 private Map<String,Object> conversationData(Conversation c){Map<String,Object> m=new LinkedHashMap<>();m.put("id",c.getId());m.put("type",c.getType());m.put("roomId",c.getRoomId());m.put("postId",c.getPostId());m.put("roommateRequestId",c.getRoommateRequestId());m.put("lastMessageId",c.getLastMessageId());m.put("lastMessageAt",c.getLastMessageAt());m.put("participants",participants.findByConversationId(c.getId()).stream().map(p->Map.of("userId",p.getUserId(),"joinedAt",p.getJoinedAt())).toList());return m;}
 private Map<String,Object> messageData(ChatMessage m){Map<String,Object> x=new LinkedHashMap<>();x.put("id",m.getId());x.put("senderId",m.getSenderId());x.put("type",m.getMessageType());x.put("content",m.getContent());x.put("sentAt",m.getSentAt());x.put("sharedPostId",m.getSharedPostId());return x;}
 private Map<String,Object> notificationData(Notification n){Map<String,Object> x=new LinkedHashMap<>();x.put("id",n.getId());x.put("type",n.getType());x.put("title",n.getTitle());x.put("content",n.getContent());x.put("isRead",n.isRead());x.put("resourceType",n.getResourceType());x.put("resourceId",n.getResourceId());x.put("createdAt",n.getCreatedAt());return x;}
 private boolean publicPost(Post p){return "APPROVED".equals(p.getStatus())&&(!"STALE".equals(p.getAvailabilityStatus()));} private Long requiredLong(JsonNode b,String k){if(b==null||!b.hasNonNull(k))throw bad(k+" là bắt buộc");return b.get(k).asLong();} private String text(JsonNode b,String k){return b!=null&&b.hasNonNull(k)?b.get(k).asText():"";} private ApiResponseDto<?> ok(String m,Object d){return ApiResponseDto.ok("/api/v1",m,d);} private ResponseStatusException bad(String m){return new ResponseStatusException(HttpStatus.BAD_REQUEST,m);} private ResponseStatusException conflict(String m){return new ResponseStatusException(HttpStatus.CONFLICT,m);} private ResponseStatusException forbidden(String m){return new ResponseStatusException(HttpStatus.FORBIDDEN,m);} private ResponseStatusException notFound(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);}
}
